package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.LogoUriVO;

class LogoUriValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of logo uri of oauth client")
  void test_logo_uri_value_holder_assign_plain_value() {
    Object holder = new Object();
    LogoUriValueHolder<Object> value = new LogoUriValueHolder<>(holder);
    Assertions.assertSame(holder, value.logoUri("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getLogoUriValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getLogoUri().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.logoUriNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getLogoUriValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getLogoUri().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of logo uri of oauth client")
  void test_logo_uri_value_holder_assign_value_object() {
    Object holder = new Object();
    LogoUriValueHolder<Object> value = new LogoUriValueHolder<>(holder);
    LogoUriVO vo = LogoUriVO.from("one");
    Assertions.assertFalse(value.getLogoUriValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.logoUri(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getLogoUriValue().orElseThrow());
    Assertions.assertSame(holder, value.logoUri(Optional.empty()));
    Assertions.assertFalse(value.getLogoUriValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.logoUri(Optional.of(vo)));
    Assertions.assertSame(vo, value.getLogoUriValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of logo uri of oauth client against the original")
  void test_logo_uri_value_holder_read() {
    Object holder = new Object();
    LogoUriValueHolder<Object> value = new LogoUriValueHolder<>(holder);
    LogoUriVO vo = LogoUriVO.from("one");
    LogoUriVO other = LogoUriVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getLogoUriValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readLogoUri(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readLogoUri(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.logoUri(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readLogoUri(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readLogoUri(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of logo uri of oauth client")
  void test_logo_uri_value_holder_unset() {
    Object holder = new Object();
    LogoUriValueHolder<Object> value = new LogoUriValueHolder<>(holder);
    LogoUriVO vo = LogoUriVO.from("one");
    value.logoUri(vo);
    Assertions.assertSame(holder, value.unsetLogoUriIfMatches("logoUri_other"));
    Assertions.assertTrue(value.getLogoUriValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetLogoUriIfMatches("logoUri"));
    Assertions.assertFalse(value.getLogoUriValue().isPresent(),
        "The field name must clear the value");
    value.logoUri(vo);
    Assertions.assertSame(holder, value.unsetLogoUri());
    Assertions.assertFalse(value.getLogoUriValue().isPresent(), "Unset must clear the value");
  }
}
